using System.IO;
using UnityEngine;

namespace prop.editor
{
    public abstract class BaseGenerated
    {
		private string content;
		protected string path;

		public BaseGenerated(string cPath)
		{
			path = cPath;
		}

		protected void WriteHeader()
		{
			content = @"
//------------------------------------------------------------------------------
// <auto-generated>
// This Script Generate By Tools.
// 工具：BudTools -> 道具工具
// </auto-generated>
//------------------------------------------------------------------------------


";
		}
		protected void WirteContinue(string tmpStr)
		{
			content += tmpStr + "\n";
		}

		protected string Replace(string tmp, string repStr)
		{
			content = content.Replace(tmp, repStr);
			return content;
		}

		protected void WriteToFile()
        {
            FileStream file = new FileStream(path, FileMode.Create);
            StreamWriter fileW = new StreamWriter(file, System.Text.Encoding.UTF8);
            fileW.Write(content);
            fileW.Flush();
            fileW.Close();
            file.Close();
			
			content = "";
            Debug.Log($"写入成功 {path} 成功.");
        }
        public abstract void Generate();
    }
}